  ('steak-cut', 'Steak cut', 'GOAT steak cut', 'Food', 'Steak cut', 'daily', null, '[{"name":"Ribeye","est":0.34},{"name":"Filet Mignon","est":0.22},{"name":"New York Strip","est":0.15},{"name":"Porterhouse","est":0.09},{"name":"T-Bone","est":0.06},{"name":"Top Sirloin","est":0.04},{"name":"Picanha","est":0.03},{"name":"Flat Iron","est":0.03},{"name":"Skirt Steak","est":0.02},{"name":"Hanger Steak","est":0.02},{"name":"Flank Steak","est":0},{"name":"Tri-Tip","est":0},{"name":"Denver Steak","est":0},{"name":"Chuck Eye","est":0},{"name":"Bavette","est":0},{"name":"Round Steak","est":0}]'::jsonb, '{"Ribeye":["It contains the longissimus dorsi muscle.","It often features substantial intramuscular fat.","It can be purchased with or without a bone.","It is cut from the same section used for prime rib."],"Filet Mignon":["It comes from a muscle that performs relatively little work.","It is generally lean with relatively little marbling.","It is cut from the beef tenderloin.","Its name is French and it is commonly served as a thick medallion."],"New York Strip":["It contains the longissimus muscle.","It is cut from the short loin.","It is also commonly called a Kansas City steak.","Its boneless form is traditionally served at American steakhouses."]}'::jsonb, 'builtin', true),
  ('bbq-food', 'BBQ food', 'GOAT BBQ food', 'Food', 'BBQ', 'daily', null, '[{"name":"Smoked Brisket","est":0.27},{"name":"Baby Back Ribs","est":0.22},{"name":"Pulled Pork","est":0.16},{"name":"Cheeseburger","est":0.12},{"name":"BBQ Chicken","est":0.07},{"name":"Steak","est":0.05},{"name":"Sausage","est":0.04},{"name":"Burnt Ends","est":0.03},{"name":"Hot Dog","est":0.02},{"name":"Grilled Shrimp","est":0.02},{"name":"Grilled Salmon","est":0},{"name":"Pork Belly","est":0},{"name":"Tri-Tip","est":0},{"name":"Turkey Leg","est":0},{"name":"Chicken Skewers","est":0},{"name":"Grilled Corn","est":0}]'::jsonb, '{"Smoked Brisket":["The cut contains substantial connective tissue.","Traditional barbecue preparation requires prolonged low-temperature cooking.","It is a signature component of Central Texas barbecue.","The beef cut comes from the lower chest of the animal."],"Baby Back Ribs":["This cut contains curved bones with meat between them.","It is commonly prepared with dry seasoning or barbecue sauce.","It comes from the upper rib cage of a pig near the spine.","Cut from the loin, its bones are shorter than the belly-side cut."],"Pulled Pork":["The dish is associated with barbecue traditions in the American South.","Shoulder meat is commonly used for its preparation.","Long cooking breaks down connective tissue and softens the meat.","The finished meat is shredded into strands and often served on a bun."]}'::jsonb, 'builtin', true),
